import { WPSP_ROOT } from './adapter.ts';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { assessBashRisk, assessBrowserScriptRisk, assessToolRisk, BROWSER_SCRIPT_TOOL, describeToolCall, splitCommand } from './adapter.ts';

describe( 'assessBashRisk', () => {
	// Commands the release commands run routinely must not stop for approval.
	it.each( [
		'git tag --sort=-v:refname | head -1',
		'git tag',
		'git tag -l "4.17.*"',
		'git tag --list',
		'git log 4.17.4..HEAD --oneline --no-merges',
		'git diff 4.17.4..HEAD --stat',
		'git status',
		'git checkout release/4.17.5',
		'gh issue view 2454 --json body,comments -q \'.body\'',
		'gh pr view 3574',
		'gh pr list --milestone 4.17.5',
		'gh api repos/awesomemotive/wp-simple-pay-pro/pulls/3574',
		'grep -rl \'{next}\' src/ includes/ views/',
		"sed -i 's/{next}/4.17.5/g' src/Foo.php",
		'npx wp-scripts build',
		'npm run docs:index',
		'npm run build:ui',
		'npm run docs:optimize-images',
		'curl -s -o /dev/null -w \'%{http_code}\' -k https://wpsp-site.local/doc/x/',
		'rm docs/releases/4.17.5/tmp.txt',
		// Staging the wp.org release only changes the local working copy.
		'bash .claude/scripts/lite-release/svn-stage.sh 4.17.5',
		'svn status "$SVN"',
		'svn diff "$SVN/trunk"',
		'svn update "$SVN"',
		'svn rm "$SVN/trunk/old-file.php"',
		'svn revert -R "$SVN/trunk"',
	] )( 'allows %j', ( command ) => {
		expect( assessBashRisk( command ) ).toBeNull();
	} );

	it.each( [
		[ 'git push origin release/4.17.5', 'git-push' ],
		[ 'git push --dry-run', 'git-push' ],
		[ 'cd ../wp-simple-pay-lite && git push -u origin release/4.17.5', 'git-push' ],
		[ 'rtk git push', 'git-push' ],
		[ 'GIT_TRACE=1 git push', 'git-push' ],
		[ 'bash -c "git push"', 'git-push' ],
		[ 'git tag 4.17.5', 'git-tag' ],
		[ 'git tag -a 4.17.5 -m "Release"', 'git-tag' ],
		[ 'git tag -d 4.17.5', 'git-tag' ],
		[ 'git commit -m "Release 4.17.5"', 'git-commit' ],
		[ 'git reset --hard origin/master', 'git-discard' ],
		[ 'git clean -fd', 'git-discard' ],
		[ 'git branch -D release/4.17.5', 'git-discard' ],
		[ 'git checkout -- .', 'git-discard' ],
		[ 'git restore readme.txt', 'git-discard' ],
		[ 'git stash drop', 'git-discard' ],
		[ 'gh release create 4.17.5 build.zip', 'gh-release' ],
		[ 'gh release upload 4.17.5 build.zip', 'gh-release' ],
		[ 'gh pr create --base master --title "Release 4.17.5"', 'gh-pr' ],
		[ 'gh pr merge 3574 --squash', 'gh-pr' ],
		[ 'gh pr comment 3574 --body "x"', 'gh-pr' ],
		[ 'gh issue close 2454', 'gh-issue' ],
		[ 'gh api -X POST repos/o/r/issues', 'gh-api-write' ],
		[ 'gh api --method DELETE repos/o/r/git/refs/tags/4.17.5', 'gh-api-release' ],
		[ 'gh api repos/o/r/issues -f title=x', 'gh-api-write' ],
		[ '"$PHP_BIN" -d memory_limit=1024M "$(command -v wp)" --path="$WP_ROOT" wpsp-docs sync', 'docs-sync' ],
		[ 'wp wpsp-docs sync --force', 'docs-sync' ],
		[ 'rsync -a --prune-empty-dirs src/ dst/', null ],
		[ 'rm -rf build', 'rm-recursive' ],
		[ 'rm -fr build', 'rm-recursive' ],
		[ 'rm -r build', 'rm-recursive' ],
		[ 'npm run build', 'npm-build' ],
		[ 'nvm use && npm run build', 'npm-build' ],
		[ 'npm publish', 'npm-publish' ],
		[ 'curl -X POST https://example.com/hook', 'curl-write' ],
		[ 'curl https://example.com/hook -d \'{"a":1}\'', 'curl-write' ],
		[ 'svn commit "$SVN/trunk" -m "Updating trunk to 4.17.5"', 'svn-commit' ],
		[ 'svn ci -m x', 'svn-commit' ],
		[ 'bash .claude/scripts/lite-release/svn-commit.sh 4.17.5', 'svn-commit' ],
		[ 'svn copy -r 123 https://plugins.svn.wordpress.org/stripe/trunk https://plugins.svn.wordpress.org/stripe/tags/4.17.5 -m "Tagging 4.17.5"', 'svn-commit' ],
		[ 'svn cp ^/trunk ^/tags/4.17.5 -m x', 'svn-commit' ],
		[ 'svn rm https://plugins.svn.wordpress.org/stripe/tags/4.17.5 -m x', 'svn-commit' ],
	] )( 'flags %j as %s', ( command, rule ) => {
		expect( assessBashRisk( command )?.rule ?? null ).toBe( rule );
	} );

	it( 'flags --prune on its own', () => {
		expect( assessBashRisk( 'some-tool sync --prune' )?.rule ).toBe( 'prune' );
	} );

	it( 'asks for the version typed before an SVN commit or tag', () => {
		expect( assessBashRisk( 'bash .claude/scripts/lite-release/svn-commit.sh 4.17.5' )?.irreversible ).toBe( true );
	} );

	it( 'gives a reason with every match', () => {
		expect( assessBashRisk( 'git push' )?.reason ).toMatch( /remote/ );
		expect( assessBashRisk( 'npm run build' )?.reason ).toMatch( /vendor/ );
	} );

	it( 'finds a risky command later in a chain', () => {
		expect( assessBashRisk( 'git status; git log -1 || git push' )?.rule ).toBe( 'git-push' );
	} );

	it( 'does not confuse a listing tag command with a later tag write', () => {
		expect( assessBashRisk( 'git tag --sort=-v:refname | head -1 && git tag 4.17.5' )?.rule ).toBe( 'git-tag' );
	} );

	it.each( [ '', '   ', null, undefined, 42, {} ] )( 'returns null for empty or non-string %j', ( command ) => {
		expect( assessBashRisk( command ) ).toBeNull();
	} );
} );

describe( 'splitCommand', () => {
	it( 'splits on chains, pipes and newlines and drops empty parts', () => {
		expect( splitCommand( 'a && b || c; d | e\nf;;' ) ).toEqual( [ 'a', 'b', 'c', 'd', 'e', 'f' ] );
	} );
} );

describe( 'irreversible actions', () => {
	it.each( [
		'gh release create 4.17.5 build.zip --title 4.17.5',
		'gh release delete 4.17.5',
		'git tag 4.17.5',
		'git tag -a 4.17.5 -m Release',
		'git push origin --tags',
		'git push --follow-tags',
		'git push origin refs/tags/4.17.5',
		'git push origin --delete 4.17.5',
		'git push origin :refs/tags/4.17.5',
		'gh api -X POST repos/o/r/releases -f tag_name=4.17.5',
		'gh api repos/o/r/git/refs -f ref=refs/tags/4.17.5 -f sha=abc',
	] )( 'marks %j as needing the version typed', ( command ) => {
		expect( assessBashRisk( command )?.irreversible ).toBe( true );
	} );

	it.each( [ 'git push origin release/4.17.5', 'gh pr create --base master', 'git commit -m x', 'npm run build', 'gh api repos/o/r/issues -f title=x' ] )(
		'does not mark %j as irreversible',
		( command ) => {
			expect( assessBashRisk( command ) ).toMatchObject( { irreversible: false } );
		}
	);

	it( 'still lets a read of releases through', () => {
		expect( assessBashRisk( 'gh api repos/o/r/releases/latest' ) ).toBeNull();
		expect( assessBashRisk( 'gh release view 4.17.4 --json tagName' ) ).toBeNull();
	} );
} );

describe( 'browser scripts', () => {
	it.each( [
		"await wp.apiFetch( { path: '/wp/v2/posts', method: 'POST', data: { status: 'draft' } } )",
		"fetch('/wp-json/wp/v2/media', { method: \"DELETE\" })",
		'jQuery.ajax({ url: x, method: `PUT` })',
		"axios.post('/x', {})",
		"$.post('/wp-admin/admin-ajax.php', data)",
	] )( 'flags a write request: %s', ( text ) => {
		expect( assessBrowserScriptRisk( { action: 'javascript_exec', text } )?.rule ).toBe( 'browser-write' );
	} );

	it( 'flags a form submit', () => {
		expect( assessBrowserScriptRisk( { text: "document.querySelector('form').submit()" } )?.rule ).toBe( 'browser-submit' );
	} );

	it.each( [
		"await wp.apiFetch( { path: '/wp/v2/posts?status=draft' } )",
		'document.title',
		"fetch('/wp-json/wp/v2/posts/1').then( r => r.json() )",
		"const method = 'POST'; console.log( method )",
	] )( 'lets a read through: %s', ( text ) => {
		expect( assessBrowserScriptRisk( { text } ) ).toBeNull();
	} );

	it( 'copes with nested and non-string input', () => {
		expect( assessBrowserScriptRisk( { args: { code: "wp.apiFetch({ method: 'PATCH' })" } } )?.rule ).toBe( 'browser-write' );
		expect( assessBrowserScriptRisk( null ) ).toBeNull();
		expect( assessBrowserScriptRisk( 42 ) ).toBeNull();
	} );

	it( 'routes each tool to the right check', () => {
		expect( assessToolRisk( 'Bash', { command: 'git push' } )?.rule ).toBe( 'git-push' );
		expect( assessToolRisk( BROWSER_SCRIPT_TOOL, { text: "wp.apiFetch({ method: 'POST' })" } )?.rule ).toBe( 'browser-write' );
		expect( assessToolRisk( 'Write', { file_path: 'x', content: "git push; wp.apiFetch({ method: 'POST' })" } ) ).toBeNull();
		expect( assessToolRisk( 'Bash', null ) ).toBeNull();
	} );

	it( 'describes the call for the approval card', () => {
		expect( describeToolCall( 'Bash', { command: 'git push' } ) ).toBe( 'git push' );
		expect( describeToolCall( BROWSER_SCRIPT_TOOL, { action: 'javascript_exec', text: 'x()', tabId: 3 } ) ).toBe( 'javascript_exec\nx()' );
	} );
} );

describe( 'browser publish guard', () => {
	it.each( [
		"document.getElementById( 'publish' ).click()",
		'document.getElementById("publish")?.click()',
		"document.querySelector('#publish').dispatchEvent(new MouseEvent('click'))",
		"document.querySelector('select[name=post_status]').value = 'publish'",
		"wp.apiFetch( { path: '/wp/v2/wpf_notification/9', data: { status: 'publish' } } )",
		"form.post_status = 'future'",
	] )( 'stops %j for a typed confirmation', ( code ) => {
		expect( assessBrowserScriptRisk( { text: code } ) ).toMatchObject( { rule: 'browser-publish', irreversible: true } );
	} );

	it.each( [
		[ 'wpsp-draft-notifications', 4 ],
		[ 'wpsp-draft-email-campaign', 4 ],
	] )( 'lets the %s command’s own page scripts run', ( name, count ) => {
		const command = readFileSync( path.join( WPSP_ROOT, `.claude/commands/${ name }.md` ), 'utf8' );
		const scripts = [ ...command.matchAll( /```js\n([\s\S]*?)```/g ) ].map( ( match ) => match[ 1 ] );

		expect( scripts.length ).toBeGreaterThanOrEqual( count );

		for ( const code of scripts ) {
			expect( assessBrowserScriptRisk( { text: code } ) ).toBeNull();
		}
	} );

	it.each( [
		"[...document.querySelectorAll('button')].find(b => b.innerText === 'Send Now').click()",
		"document.querySelector('[data-action=schedule]').click() // Schedule",
		"buttons.find(b => /Save & Review/.test(b.innerText)).dispatchEvent(new MouseEvent('click', { bubbles: true }))",
		"findButton('Send Test Email').click()",
	] )( 'stops a script that clicks a send button: %j', ( code ) => {
		expect( assessBrowserScriptRisk( { text: code } ) ).toMatchObject( { rule: 'browser-send', irreversible: true } );
	} );

	it( 'lets a script click plain Save', () => {
		expect( assessBrowserScriptRisk( { text: "[...document.querySelectorAll('button')].find(b => b.innerText.trim() === 'Save').click()" } ) ).toBeNull();
	} );
} );
